/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_v_id_set_delete (ID_Set * id_set)
{
  ID_Range * id_range ;

  while ((id_range = can_v_id_set_peek_rhs (id_set))!= FALSE)  // added the check against False to eliminate compiler warnings
    {
      can_v_id_range_unlink (id_range) ;

      can_v_id_range_delete (id_range) ;
    }

  can_v_mem_release (id_set) ;
}

